class Solution {
public:
    vector<int> maxTargetNodes(vector<vector<int>>& edges1, vector<vector<int>>& edges2, int k) {
        int n = edges1.size() + 1;
        int m = edges2.size() + 1;

        vector<vector<int>> adj1(n), adj2(m);
        for (auto& e : edges1) {
            adj1[e[0]].push_back(e[1]);
            adj1[e[1]].push_back(e[0]);
        }
        for (auto& e : edges2) {
            adj2[e[0]].push_back(e[1]);
            adj2[e[1]].push_back(e[0]);
        }

        auto countWithin = [&](vector<vector<int>>& adj, int nodes, int maxDist) -> vector<int> {
            vector<int> result(nodes, 0);
            if (maxDist < 0) return result;
            for (int start = 0; start < nodes; start++) {
                vector<int> dist(nodes, -1);
                queue<int> q;
                q.push(start);
                dist[start] = 0;
                int cnt = 0;
                while (!q.empty()) {
                    int u = q.front(); q.pop();
                    if (dist[u] > maxDist) continue;
                    cnt++;
                    for (int v : adj[u]) {
                        if (dist[v] == -1) {
                            dist[v] = dist[u] + 1;
                            q.push(v);
                        }
                    }
                }
                result[start] = cnt;
            }
            return result;
        };

        vector<int> cnt1 = countWithin(adj1, n, k);

        int max2 = 0;
        if (k >= 1) {
            vector<int> cnt2 = countWithin(adj2, m, k - 1);
            for (int x : cnt2) max2 = max(max2, x);
        }

        vector<int> answer(n);
        for (int i = 0; i < n; i++) {
            answer[i] = cnt1[i] + max2;
        }
        return answer;
    }
};
